<script setup lang="ts">
import {ref,onUnmounted} from 'vue';
import TownMap from './TownMap.vue';
import ModelCenter from './ModelCenter.vue';
import Governance from './Governance.vue';
import WorldPanel from './WorldPanel.vue';
import type {World} from '../../../packages/shared/src/types';
const password=ref(''),world=ref<World>(),error=ref(''),connected=ref(false),selection=ref<any>(),busy=ref(false);
const tab=ref('office');
const tile=ref<{x:number;y:number}>();
let ws:WebSocket|undefined,reconnect:ReturnType<typeof setTimeout>,disposed=false;
async function api(path:string,body?:any){const r=await fetch(path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const v=await r.json();if(!r.ok)throw new Error(v.message);return v;}
async function load(){try{const id=new URLSearchParams(location.search).get('world');world.value=await api(id?`/api/worlds/${encodeURIComponent(id)}/state`:'/api/worlds/starter/state');connect();}catch(e:any){error.value=e.message;}}
function connect(){ws?.close();ws=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/ws/${world.value!.id}`);ws.onmessage=e=>{world.value=JSON.parse(e.data).state;connected.value=true;};ws.onclose=()=>{connected.value=false;if(!disposed)reconnect=setTimeout(connect,2000);};}
async function switchWorld(id:string){try{world.value=await api(`/api/worlds/${id}/state`);selection.value=undefined;connect();}catch(e:any){error.value=e.message;}}
async function login(){busy.value=true;try{await api('/api/login',{password:password.value});password.value='';await load();error.value='';}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
async function control(action:string,speed?:number){try{world.value=await api(`/api/worlds/${world.value!.id}/control`,{action,speed,key:crypto.randomUUID(),expectedVersion:world.value!.version});error.value='';}catch(e:any){error.value=e.message;}}
void load();onUnmounted(()=>{disposed=true;clearTimeout(reconnect);ws?.close();});
</script>
<template>
 <main v-if="!world" class="login"><div class="eyebrow">AI FRONTIER TOWN</div><h1>风沙之中，<br>建立一个新世界。</h1><p>晨沙镇 · 新历第 1 年</p><form @submit.prevent="login"><label>镇长通行密码<input v-model="password" type="password" required autocomplete="current-password"></label><button :disabled="busy">进入晨沙镇 →</button></form><p class="error">{{error}}</p></main>
 <main v-else class="shell"><header><div><span class="eyebrow">THE DESERT FRONTIER</span><h1>晨沙镇 <small>开拓委员会</small></h1></div><div class="clock">第 {{Math.floor(world.gameTime/1440)+1}} 天 · {{String(Math.floor(world.gameTime%1440/60)).padStart(2,'0')}}:{{String(Math.floor(world.gameTime%60)).padStart(2,'0')}}<span :class="connected?'online':'error'">● {{connected?'世界已连接':'正在重连'}}</span></div><div class="controls"><button @click="control(world.running?'pause':'resume')">{{world.running?'Ⅱ 暂停':'▶ 继续'}}</button><button v-for="speed in [1,2,4]" :class="{active:world.speed===speed}" @click="control('speed',speed)">{{speed}}×</button></div></header>
 <div class="resource-bar"><span v-for="(v,k) in world.resources"><small>{{({water:'水库存',food:'粮食',cash:'公共财政',stone:'石料',wood:'木料',tools:'工具'} as any)[k]??k}}</small><strong>{{Math.round(v).toLocaleString()}}</strong></span></div>
 <nav><button @click="tab='office'">镇长办公</button><button @click="tab='proposals'">发布提案</button><button @click="tab='planning'">地图规划</button><button @click="tab='projects'">施工项目</button><button @click="tab='finance'">财政</button><button @click="tab='residents'">居民</button><button @click="tab='dialogue'">对话观察</button><button @click="tab='events'">公告</button><button @click="tab='frontier'">探索</button><button @click="tab='experiments'">决策实验</button><button @click="tab='models'">模型中心</button><button @click="tab='settings'">世界设置</button></nav>
 <div class="workspace"><section class="map-wrap"><TownMap :world="world" @select="selection=$event;if(!['planning','proposals'].includes(tab))tab='office'" @tile="tile=$event"/><div class="map-note">晨沙镇 · 古井营地 <span>拖动地图 / 滚轮缩放 / 点击人物与建筑</span></div></section><aside><WorldPanel v-if="['settings','events','frontier','experiments'].includes(tab)" :world="world" :tile="tile" :tab="tab" @updated="world=$event" @switch="switchWorld"/><Governance v-else-if="['proposals','planning','projects','finance'].includes(tab)" :world="world" :tile="tile" :tab="tab" @updated="world=$event"/><ModelCenter v-else-if="tab==='models'" :world="world" @updated="world=$event"/><template v-else-if="tab==='residents'"><h2>开拓居民</h2><button v-for="r in world.residents" @click="selection={kind:'resident',data:r};tab='office'">{{r.name}} · {{r.current_action}}</button></template><template v-else-if="tab==='dialogue'"><h2>公开对话</h2><div v-for="c in world.conversations.slice(-10).reverse()" class="notice"><strong>{{c.topic}} · {{c.status}}</strong><p v-for="m in c.messages">{{world.residents.find(r=>r.id===m.speakerId)?.name}}：{{m.text}}</p></div></template><template v-else><div class="eyebrow">MAYOR'S DESK</div><h2>{{selection?.data.name??'新世界，第一天'}}</h2><template v-if="selection"><p>{{selection.kind==='resident'?'开拓居民':'聚落设施'}}</p><p>位置 {{selection.data.x}}, {{selection.data.y}}</p><p>{{selection.data.role??selection.data.type}}</p><template v-if="selection.kind==='resident'"><p>{{world.residents.find(r=>r.id===selection.data.id)?.current_action}}</p><p>{{selection.data.background}}</p><p v-for="g in selection.data.goals">{{g.term}} · {{g.content}}</p><h3>已公开经历</h3><p v-for="m in selection.data.memories">{{m.content}}</p><h3>有向关系</h3><p v-for="(v,k) in selection.data.relations">{{world.residents.find(r=>r.id===k)?.name}}：信任{{(v as any).trust}} / 好感{{(v as any).affection}}</p></template></template><template v-else><p>车队停在古井旁。帐篷刚刚架好，镇子的故事即将开始。</p><p>世界时间与地图由服务端保存。关闭网页不会丢失进度。</p></template></template><p class="error">{{error}}</p></aside></div>
 <footer><span>晨沙镇 · 自托管的沙海开拓世界</span><span>第 {{world.version}} 次状态更新</span></footer></main>
</template>
